INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷80·晋高祖本纪·天福七年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7e9f7a7ea4b22cbbe6d05277dd5c16ed51a9e06/content/books/zizhi-tongjian/vol-283/year-0942/part-01/sources/library/jiuwudaishi-080-942-january/source.txt", "note": "《旧五代史》卷80·晋高祖本纪·天福七年正月，段落 jiu-wudaishi-205deb4a7860-p001966；已核上下文及传主，纸本及异文待核。", "id": "085a4798-3858-516e-a574-8042ad35029a"}, {"title": "资治通鉴·卷283·天福七年春季", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7e9f7a7ea4b22cbbe6d05277dd5c16ed51a9e06/content/books/zizhi-tongjian/vol-283/year-0942/part-01/sources/library/tongjian-283-942-spring/source.txt", "note": "《资治通鉴》卷283·天福七年春季，段落 zizhi-tongjian-a63549944a71-p003360；已核上下文及传主，纸本及异文待核。", "id": "51e3045e-685e-5f80-bb8e-2efc7cd67ab5"}, {"title": "新五代史·卷68·闽世家·王延羲妻李氏", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7e9f7a7ea4b22cbbe6d05277dd5c16ed51a9e06/content/books/zizhi-tongjian/vol-283/year-0942/part-01/sources/library/xinwudaishi-068-min-li-empress/source.txt", "note": "《新五代史》卷68·闽世家·王延羲妻李氏，段落 xin-wudaishi-b08f244b9241-p003411；已核上下文及传主，纸本及异文待核。", "id": "f65572e7-91e0-5d18-a84c-68aa6429f9d4"}, {"title": "新五代史·卷74·四夷附录·陈延晖赴凉州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7e9f7a7ea4b22cbbe6d05277dd5c16ed51a9e06/content/books/zizhi-tongjian/vol-283/year-0942/part-01/sources/library/xinwudaishi-074-chen-yanhui/source.txt", "note": "《新五代史》卷74·四夷附录·陈延晖赴凉州，段落 xin-wudaishi-b08f244b9241-p003654；已核上下文及传主，纸本及异文待核。", "id": "e7a8e6a1-848c-511c-bc90-896eadcd0a8d"}, {"title": "旧五代史·卷98·安重荣传·宗城之战", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/058e3fb21c9297c339adaaf269129242f63ad9e2/content/books/zizhi-tongjian/vol-282/year-0941/part-06/sources/library/jiuwudaishi-098-zongcheng/source.txt", "note": "《旧五代史》卷98·安重荣传·宗城之战，段落 jiu-wudaishi-205deb4a7860-p002394；已核上下文及传主，纸本及异文待核。", "id": "77f1f691-8569-5ce3-b70b-59af25e7625c"}, {"title": "新五代史·卷51·安重荣传·宗城之战", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/058e3fb21c9297c339adaaf269129242f63ad9e2/content/books/zizhi-tongjian/vol-282/year-0941/part-06/sources/library/xinwudaishi-051-zongcheng/source.txt", "note": "《新五代史》卷51·安重荣传·宗城之战，段落 xin-wudaishi-b08f244b9241-p002004；已核上下文及传主，纸本及异文待核。", "id": "db0641bc-c32f-5077-a5c2-ef76385d9e13"}]'::jsonb)
