INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "安重荣", "aliases": ["安重榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安重荣，转投者。", "biography": null, "status": "draft", "id": "7309cd08-206a-5781-8eaa-527f54f64299"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "赵莹", "aliases": ["趙瑩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵莹，劝赴任者。", "biography": null, "status": "draft", "id": "1f5a50e7-b046-593f-8be4-621934211b27"}, {"name": "王瑜", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "范阳人，后晋卫尉少卿。942年杜重威奏请让他任副使；《资治通鉴》记他为杜重威向恒州百姓重征赋税。生卒年未载。", "biography": null, "status": "draft", "id": "bd57ed18-81ea-5191-9eb0-0bfa41b1fc06"}, {"name": "张铎", "aliases": ["張鐸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋张式的父亲。942年到朝廷为儿子申冤。生卒年未载。", "biography": null, "status": "draft", "id": "76a2426d-a082-5fa7-a7a7-f4d155e0cce6"}, {"name": "张式", "aliases": ["張式"], "era": "五代十国", "birth_year": null, "death_year": 941, "description": "张彦泽的掌书记，曾受到信任。941年劝阻张彦泽杀子，遭射箭、谗言和追捕；李周为他上报朝廷后，仍被石敬瑭交还张彦泽，二月癸未在泾州遇害。新旧五代史对逃亡路线有异说。出生年未载。", "biography": null, "status": "draft", "id": "f0a85d86-b611-526b-8a8a-5263d0de38e3"}, {"name": "王周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262天复元年条所见人物：王周。", "biography": null, "status": "draft", "id": "dcf3a493-1cbc-5185-9787-8041333d1d90"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "李氏（王延羲后）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国同平章事李真的女儿，王延羲的妻子。942年被立为皇后。《资治通鉴》和《新五代史》都记她嗜酒，性格强硬。姓名及生卒年未载。", "biography": null, "status": "draft", "id": "eb943b54-1a2c-5d87-8764-6486416880c7"}, {"name": "李真", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员。939年王延羲即位后，将已以太子太傅身份退休的李真任为司空兼中书侍郎、同平章事。生卒年未载。", "biography": null, "status": "draft", "id": "be8de9d6-a061-55a2-9434-5f7e8c2a8702"}, {"name": "丁审琦", "aliases": ["丁審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：丁审琦，守忻州刺史。", "biography": null, "status": "draft", "id": "df972050-8042-5418-a3bc-62faa87fcfa7"}, {"name": "贺行政", "aliases": ["賀行政"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "延州军校。942年年初与胡人联合作乱，进攻延州。生卒年未载。", "biography": null, "status": "draft", "id": "6bdec56f-118e-59aa-91e3-c83f1f496e8d"}, {"name": "何重建", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋曹州防御使，云州、朔州一带胡人。942年受命援救延州，二月被任命为彰武留后。生卒年未载。", "biography": null, "status": "draft", "id": "32fa2f01-0372-5b5b-83b5-c66e445ba1c1"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "徐景遂", "aliases": ["景遂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐景遂，获任者。", "biography": null, "status": "draft", "id": "cb45cc6e-58fb-5804-8c3d-962cbbc03a13"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "夏昌图", "aliases": ["夏昌圖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宋齐丘身边的亲近吏员。《资治通鉴》942年条下记他盗用官钱三千缗，宋齐丘准免死刑，李昪愤怒并杀死他。生卒年月未载。", "biography": null, "status": "draft", "id": "eecafddb-635d-5d1f-bc85-151bfc0b001e"}, {"name": "陈延晖", "aliases": ["陳延暉", "陈延暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泾州押牙。《资治通鉴》942年条下记他持敕书前往凉州，当地将吏请求让他任节度使。《新五代史》记他被留下并立为刺史，连叙纪年有异。生卒年未载。", "biography": null, "status": "draft", "id": "cb63f3a6-342d-5bc1-9084-2520ae96de40"}, {"name": "王亚澄", "aliases": ["王亞澄"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽王王延羲的儿子。941年四月被任命为同平章事，主管六军诸卫。生卒年未载。", "biography": null, "status": "draft", "id": "bdfe7b21-c8f9-5a2a-8792-e061e8da5652"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
